sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var body = request.body.dataString;

        if (!body) {
            response.setStatus(400);
            response.setBody({
                status: 'error',
                message: 'Request body is empty'
            });
            return;
        }

        var gr = new GlideRecord('x_2226556_server_0_canopi_stg');
        gr.initialize();
        gr.setValue('payload', body);
        gr.setValue('source_system', 'CANOPI');
        gr.setValue('http_response_code', '202');
        var sysId = gr.insert();

        if (sysId) {
            response.setStatus(202);
            response.setBody({
                status: 'accepted',
                staging_sys_id: String(sysId),
                message: 'Payload accepted for processing'
            });
        } else {
            response.setStatus(500);
            response.setBody({
                status: 'error',
                message: 'Failed to create staging record'
            });
        }
    } catch (e) {
        gs.error('CANOPI ingest handler error: ' + e);
        response.setStatus(500);
        response.setBody({
            status: 'error',
            message: 'Internal server error during payload ingestion'
        });
    }
})(request, response);
